-- (is_demo already exists on orders from 0001 — not added again.)

-- "No orphan PO": a PO may only exist against an APPROVED quote. quote_id is already NOT NULL,
-- so the rule that needs enforcing is the quote's status, which a CHECK cannot see.
create or replace function public.check_order_quote_approved()
returns trigger
language plpgsql
as $$
declare
  q public.quote_status;
begin
  select status into q from public.quotes where id = new.quote_id;
  if q is distinct from 'approved' then
    raise exception 'Order requires an approved quote; quote % is %', new.quote_id, coalesce(q::text, 'missing');
  end if;
  return new;
end;
$$;

create trigger order_requires_approved_quote
  before insert or update on public.orders
  for each row execute function public.check_order_quote_approved();

create table public.order_lines (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders(id) on delete cascade,
  requirement_line_id uuid references public.requirement_lines(id),
  part_number text not null,
  quantity_ordered integer not null check (quantity_ordered > 0),
  unit_price numeric(14,2) not null check (unit_price >= 0),
  delivery_schedule date,
  is_demo boolean not null default false
);

create table public.material_readiness (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders(id) on delete cascade,
  oem_id uuid not null references public.oems(id),
  part_number text not null,
  quantity_ready integer not null default 0 check (quantity_ready >= 0),
  manufacturing_status text not null default 'in_production'
    check (manufacturing_status in ('in_production','ready')),
  internal_qc_status text not null default 'pending'
    check (internal_qc_status in ('pending','approved')),
  batch_number text,
  serial_numbers text,
  tentative_pdi_date date,
  remarks text,
  is_demo boolean not null default false
);

alter table public.pdi_records
  add column part_number text,
  add column oem_id uuid references public.oems(id),
  add column customer_id uuid references public.customers(id),
  add column inspection_type text check (inspection_type in ('physical','vc','third_party')),
  add column agency text,
  add column inspection_date date,
  add column inspector text,
  add column rejection_reason text,
  add column re_pdi_required boolean not null default false,
  add column status text not null default 'pending'
    check (status in ('pending','passed','failed')),
  add column dispatch_clearance text not null default 'hold'
    check (dispatch_clearance in ('approved','hold'));

alter table public.oem_invoices
  add column invoice_date date,
  add column pdi_id uuid references public.pdi_records(id),
  add column customer_id uuid references public.customers(id),
  add column oem_id uuid references public.oems(id),
  add column part_number text,
  add column quantity_invoiced integer,
  add column invoice_type text check (invoice_type in ('full','partial')),
  add column balance_qty integer,
  add column net_amount numeric(14,2),
  add column gst_amount numeric(14,2),
  add column dispatch_date date,
  add column lr_awb text,
  add column courier text,
  add column eway_bill text,
  add column documents_submitted text,
  add column multiple_against_po boolean not null default false,
  add column status text not null default 'raised'
    check (status in ('raised','submitted','approved','paid'));

alter table public.payments
  add column payment_ref text,
  add column payment_terms text,
  add column mode text check (mode in ('rtgs','neft','wire','other')),
  add column proof_path text,
  add column followup_status text not null default 'pending'
    check (followup_status in ('pending','escalated','closed'));

alter table public.deliveries
  add column delivery_ref text,
  add column oem_invoice_id uuid references public.oem_invoices(id),
  add column location text,
  add column status text not null default 'in_transit'
    check (status in ('in_transit','delivered')),
  add column acceptance text check (acceptance in ('accepted','rejected')),
  add column grn_number text,
  add column pod_path text,
  add column closure_status text not null default 'pending'
    check (closure_status in ('pending','closed')),
  add column remarks text;

-- ---------------------------------------------------------------------------
-- Commission (only after the OEM-payment milestone)
-- ---------------------------------------------------------------------------

create table public.commission_invoices (
  id uuid primary key default gen_random_uuid(),
  commission_no text not null unique,
  oem_invoice_id uuid not null references public.oem_invoices(id),
  oem_id uuid not null references public.oems(id),
  customer_id uuid references public.customers(id),
  commission_pct numeric(6,2) not null check (commission_pct >= 0),
  base_amount numeric(14,2) not null check (base_amount >= 0),
  commission_amount numeric(14,2) not null check (commission_amount >= 0),
  gst_amount numeric(14,2) not null default 0,
  gross_value numeric(14,2) not null default 0,
  invoice_date date not null,
  due_date date,
  payment_status text not null default 'pending'
    check (payment_status in ('pending','paid')),
  received_on date,
  tds_deducted boolean not null default false,
  outstanding_amount numeric(14,2),
  attachment_path text,
  remarks text,
  is_demo boolean not null default false,
  created_at timestamptz not null default now()
);

-- The milestone rule, made structural: a commission invoice needs a real payment on its OEM invoice.
create or replace function public.check_commission_milestone()
returns trigger
language plpgsql
as $$
begin
  if not exists (
    select 1 from public.payments
    where oem_invoice_id = new.oem_invoice_id
  ) then
    raise exception 'Commission cannot be raised before the OEM-payment milestone (invoice %)',
      new.oem_invoice_id;
  end if;
  return new;
end;
$$;

create trigger commission_milestone
  before insert or update on public.commission_invoices
  for each row execute function public.check_commission_milestone();

-- ---------------------------------------------------------------------------
-- Audit + RLS for the new tables
-- ---------------------------------------------------------------------------

do $$
declare
  t text;
begin
  foreach t in array array[
    'customers','customer_contacts','products','product_oems','order_lines',
    'material_readiness','commission_invoices'
  ] loop
    execute format('alter table public.%1$I enable row level security', t);
    execute format(
      'create policy owner_all on public.%1$I for all
       using (public.is_owner()) with check (public.is_owner())', t);
    execute format(
      'create trigger audit_%1$s after insert or update or delete on public.%1$I
       for each row execute function public.write_audit()', t);
  end loop;
end $$;

create index order_lines_order_idx on public.order_lines(order_id);
create index material_readiness_order_idx on public.material_readiness(order_id);
create index oem_invoices_order_idx on public.oem_invoices(order_id);
create index payments_oem_invoice_idx on public.payments(oem_invoice_id);
create index commission_oem_invoice_idx on public.commission_invoices(oem_invoice_id);
create index products_part_idx on public.products using gin (part_number gin_trgm_ops);

-- ==================== supabase/migrations/0006_profiles_on_signup.sql ====================
-- 0006_profiles_on_signup.sql — give every new auth user a profiles row (and therefore a role).
-- Why: 0004's RLS policies call current_app_role(), which reads profiles. A signed-in user with
-- no profile row has role NULL, so every policy denies. This trigger closes that trap.
-- Apply in the SQL editor AFTER 0001-0005, and BEFORE creating the user (so the trigger fires).
-- STATUS: written, not yet applied.

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, full_name, role)
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'full_name', new.email),
    coalesce(nullif(new.raw_user_meta_data ->> 'role', '')::public.app_role, 'owner')
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- The role defaults to 'owner' (Ram is the principal). Change it deliberately for other users:
--   update public.profiles set role = 'sales' where id = '<user-uuid>';
--
-- If you already created a user BEFORE applying this migration, add their profile by hand:
--   insert into public.profiles (id, full_name, role)
--   select id, email, 'owner' from auth.users where email = '<your-email>'
--   on conflict (id) do nothing;

-- ==================== supabase/migrations/0007_quote_line_pricing.sql ====================
-- 0007_quote_line_pricing.sql — expose the recommended price on quote lines, computed in SQL.
-- Why: the pricing rule must live once, in SQL (docs/TECH-STACK.md), not be recomputed in the app.
-- recommended_price() is IMMUTABLE, so it can back a generated column.
-- Apply in the SQL editor after 0001-0006. STATUS: written, not yet applied.

alter table public.quote_version_lines
  add column if not exists recommended_price numeric(14,2)
  generated always as (public.recommended_price(oem_price, target_margin_pct)) stored;

-- Check: select oem_price, target_margin_pct, recommended_price from public.quote_version_lines limit 5;

-- ==================== supabase/migrations/0008_create_requirement.sql ====================
-- 0008_create_requirement.sql — create a requirement and its lines atomically.
-- Why a function: the header plus lines must save together or not at all. Two REST calls can
-- leave a header with no lines if the second fails; one function is one transaction.
-- SECURITY INVOKER (the default) means RLS applies to the caller, so a user who cannot insert
-- requirements cannot insert them through this function either.
-- Apply in the SQL editor after 0001-0007. STATUS: written, not yet applied.

create or replace function public.create_requirement_with_lines(
  p_ref text,
  p_customer text,
  p_status public.requirement_status,
  p_submission_deadline date,
  p_lines jsonb
)
returns uuid
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_id uuid;
  v_line jsonb;
  v_no integer := 0;
begin
  if p_lines is null or jsonb_array_length(p_lines) = 0 then
    raise exception 'A requirement needs at least one line item';
  end if;

  insert into public.requirements (ref, customer, status, submission_deadline, is_demo)
  values (p_ref, p_customer, p_status, p_submission_deadline, false)
  returning id into v_id;

  for v_line in select * from jsonb_array_elements(p_lines) loop
    v_no := v_no + 1;
    insert into public.requirement_lines
      (requirement_id, line_no, part_number, description, quantity, uom, deadline, is_demo)
    values (
      v_id,
      v_no,
      v_line ->> 'part_number',
      coalesce(v_line ->> 'description', ''),
      (v_line ->> 'quantity')::integer,
      v_line ->> 'uom',
      (v_line ->> 'deadline')::date,
      false
    );
  end loop;

  return v_id;
end;
$$;

-- ==================== supabase/migrations/0009_create_order_from_quote.sql ====================
-- 0009_create_order_from_quote.sql — turn an APPROVED quote into an order and its lines, atomically.
-- The "no orphan PO" rule: only an approved quote can become an order. The orders trigger
-- enforces it too, but this gives a clear message and copies the lines in one transaction.
-- SECURITY INVOKER: RLS applies to the caller.
-- Apply in the SQL editor after 0001-0008. STATUS: written, not yet applied.

create or replace function public.create_order_from_quote(
  p_quote_id uuid,
  p_po_number text,
  p_po_date date,
  p_po_value numeric
)
returns uuid
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_quote public.quotes;
  v_order_id uuid;
begin
  select * into v_quote from public.quotes where id = p_quote_id;
  if v_quote.id is null then
    raise exception 'Quote % not found', p_quote_id;
  end if;
  if v_quote.status <> 'approved' then
    raise exception 'Only an approved quote can become an order (this quote is %)', v_quote.status;
  end if;

  if exists (
    select 1
    from public.quote_versions qv
    join public.quote_version_lines qvl on qvl.quote_version_id = qv.id
    where qv.quote_id = p_quote_id
      and qv.version_no = v_quote.current_version
      and qvl.final_price is null
  ) then
    raise exception 'Every quote line needs a final price before an order can be created';
  end if;

  insert into public.orders
    (quote_id, requirement_id, po_number, po_date, po_value, status,
     partial_allowed, pdi_required, is_demo)
  values
    (p_quote_id, v_quote.requirement_id, p_po_number, p_po_date, p_po_value, 'processing',
     true, true, false)
  returning id into v_order_id;

  insert into public.order_lines
    (order_id, requirement_line_id, part_number, quantity_ordered, unit_price, is_demo)
  select v_order_id, qvl.requirement_line_id, rl.part_number, rl.quantity, qvl.final_price, false
  from public.quote_versions qv
  join public.quote_version_lines qvl on qvl.quote_version_id = qv.id
  join public.requirement_lines rl on rl.id = qvl.requirement_line_id
  where qv.quote_id = p_quote_id and qv.version_no = v_quote.current_version;

  if not exists (select 1 from public.order_lines where order_id = v_order_id) then
    raise exception 'The approved quote has no line items to order';
  end if;

  return v_order_id;
end;
$$;

-- ==================== supabase/migrations/0010_raise_commission.sql ====================
-- 0010_raise_commission.sql — raise a commission invoice from an OEM invoice.
-- The commission percentage and GST are applied in SQL, so the money figure is computed in one
-- place. The check_commission_milestone trigger (0005) already forbids a commission invoice
-- before an OEM payment exists; this function adds a clearer message and computes the amounts.
-- SECURITY INVOKER: RLS applies to the caller.
-- NOTE: the commission rule is assumption A5, not client-confirmed. Implemented as stated.
-- Apply in the SQL editor after 0001-0009. STATUS: written, not yet applied.

create or replace function public.raise_commission_invoice(
  p_oem_invoice_id uuid,
  p_commission_no text,
  p_commission_pct numeric,
  p_invoice_date date
)
returns uuid
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_invoice public.oem_invoices;
  v_base numeric;
  v_commission numeric;
  v_gst numeric;
  v_gross numeric;
  v_id uuid;
begin
  select * into v_invoice from public.oem_invoices where id = p_oem_invoice_id;
  if v_invoice.id is null then
    raise exception 'OEM invoice % not found', p_oem_invoice_id;
  end if;
  if v_invoice.oem_id is null then
    raise exception 'The OEM invoice has no OEM, so a commission cannot be raised against it';
  end if;
  if not exists (select 1 from public.payments where oem_invoice_id = p_oem_invoice_id) then
    raise exception 'Commission cannot be raised before the OEM-payment milestone is met';
  end if;
  if p_commission_pct is null or p_commission_pct < 0 then
    raise exception 'Commission percentage must be zero or greater';
  end if;

  v_base := coalesce(v_invoice.gross_amount, 0);
  v_commission := round(v_base * p_commission_pct / 100.0, 2);
  v_gst := round(v_commission * 0.18, 2);
  v_gross := v_commission + v_gst;

  insert into public.commission_invoices
    (commission_no, oem_invoice_id, oem_id, commission_pct, base_amount, commission_amount,
     gst_amount, gross_value, invoice_date, payment_status, outstanding_amount, is_demo)
  values
    (p_commission_no, p_oem_invoice_id, v_invoice.oem_id, p_commission_pct, v_base, v_commission,
     v_gst, v_gross, p_invoice_date, 'pending', v_gross, false)
  returning id into v_id;

  return v_id;
end;
$$;

-- ==================== supabase/migrations/0011_followup_tasks.sql ====================
-- 0011_followup_tasks.sql — the follow-up reminder queue.
-- A re-runnable generator that turns stale records into tasks. Idempotent: every task carries a
-- dedupe_key with a unique index, so running it twice does not duplicate a task.
-- SECURITY INVOKER: RLS applies to the caller. If run by pg_cron it runs privileged, which is fine.
-- Apply in the SQL editor after 0001-0010. STATUS: written, not yet applied.

alter table public.tasks add column if not exists dedupe_key text;
create unique index if not exists tasks_dedupe_key_idx on public.tasks(dedupe_key);

create or replace function public.generate_followup_tasks()
returns integer
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_count integer := 0;
  v_rows integer;
begin
  -- Quotes silent for 7 days
  insert into public.tasks (kind, title, owner_type, owner_id, due_date, dedupe_key, is_demo)
  select 'quote_followup',
         'Chase quote ' || coalesce(r.ref, q.id::text),
         'quote', q.id, current_date, 'quote:' || q.id || ':7d', false
  from public.quotes q
  join public.requirements r on r.id = q.requirement_id
  where q.status in ('draft', 'pending_approval')
    and q.created_at <= now() - interval '7 days'
  on conflict (dedupe_key) do nothing;
  get diagnostics v_rows = row_count;
  v_count := v_count + v_rows;

  -- OEM requests with no response for 7 days
  insert into public.tasks (kind, title, owner_type, owner_id, due_date, dedupe_key, is_demo)
  select 'oem_followup',
         'Chase OEM response (' || o.name || ')',
         'oem_request', req.id, current_date, 'oemreq:' || req.id, false
  from public.oem_requests req
  join public.oems o on o.id = req.oem_id
  where req.responded_at is null
    and req.requested_at <= now() - interval '7 days'
  on conflict (dedupe_key) do nothing;
  get diagnostics v_rows = row_count;
  v_count := v_count + v_rows;

  -- Invoices due within 7 days with an outstanding balance
  insert into public.tasks (kind, title, owner_type, owner_id, due_date, dedupe_key, is_demo)
  select 'payment_due',
         'Payment due on ' || i.invoice_no,
         'oem_invoice', i.id, i.due_date, 'invoice:' || i.id || ':' || i.due_date, false
  from public.oem_invoices i
  where i.due_date is not null
    and i.due_date <= current_date + 7
    and i.gross_amount > coalesce(
      (select sum(p.amount) from public.payments p where p.oem_invoice_id = i.id), 0)
  on conflict (dedupe_key) do nothing;
  get diagnostics v_rows = row_count;
  v_count := v_count + v_rows;

  -- Documents expiring within 60 days (or already expired)
  insert into public.tasks (kind, title, owner_type, owner_id, due_date, dedupe_key, is_demo)
  select 'document_expiry',
         'Document expiring: ' || d.title,
         'document', d.id, d.expiry_date, 'doc:' || d.id || ':' || d.expiry_date, false
  from public.documents d
  where d.expiry_date is not null
    and d.expiry_date <= current_date + 60
  on conflict (dedupe_key) do nothing;
  get diagnostics v_rows = row_count;
  v_count := v_count + v_rows;

  return v_count;
end;
$$;

-- To run it on a schedule, enable the pg_cron extension (Dashboard -> Database -> Extensions),
-- then run once:
--   select cron.schedule('generate-followups', '0 6 * * *',
--                        $$select public.generate_followup_tasks();$$);
-- and check with: select * from cron.job;

-- ==================== supabase/migrations/0012_update_requirement.sql ====================
-- 0012_update_requirement.sql — edit a requirement header and its lines in one transaction.
-- Existing lines are updated in place (by id); new lines (no id) are appended. Deleting a line is
-- deliberately not offered yet, because commitments and quote lines reference line ids.
-- SECURITY INVOKER: RLS applies to the caller.
-- Apply in the SQL editor after 0001-0011. STATUS: written, not yet applied.

create or replace function public.update_requirement_with_lines(
  p_id uuid,
  p_ref text,
  p_customer text,
  p_status public.requirement_status,
  p_submission_deadline date,
  p_loss_reason public.loss_reason,
  p_notes text,
  p_lines jsonb
)
returns void
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_line jsonb;
  v_no integer;
begin
  update public.requirements
     set ref = p_ref,
         customer = p_customer,
         status = p_status,
         submission_deadline = p_submission_deadline,
         loss_reason = p_loss_reason,
         notes = p_notes
   where id = p_id;
  if not found then
    raise exception 'Requirement % not found', p_id;
  end if;

  if p_lines is null or jsonb_array_length(p_lines) = 0 then
    raise exception 'A requirement needs at least one line item';
  end if;

  select coalesce(max(line_no), 0) into v_no
  from public.requirement_lines where requirement_id = p_id;

  for v_line in select * from jsonb_array_elements(p_lines) loop
    if (v_line ->> 'id') is not null and (v_line ->> 'id') <> '' then
      update public.requirement_lines
         set part_number = v_line ->> 'part_number',
             description = coalesce(v_line ->> 'description', ''),
             quantity = (v_line ->> 'quantity')::integer,
             uom = v_line ->> 'uom',
             deadline = (v_line ->> 'deadline')::date
       where id = (v_line ->> 'id')::uuid and requirement_id = p_id;
      if not found then
        raise exception 'Line % does not belong to this requirement', v_line ->> 'id';
      end if;
    else
      v_no := v_no + 1;
      insert into public.requirement_lines
        (requirement_id, line_no, part_number, description, quantity, uom, deadline, is_demo)
      values (
        p_id, v_no, v_line ->> 'part_number', coalesce(v_line ->> 'description', ''),
        (v_line ->> 'quantity')::integer, v_line ->> 'uom', (v_line ->> 'deadline')::date, false
      );
    end if;
  end loop;
end;
$$;

-- ==================== supabase/migrations/0013_add_commitment.sql ====================
-- 0013_add_commitment.sql — record a firm or indicative OEM commitment against a line.
-- Computes the next shipment sequence for the (line, OEM) pair so multiple shipments do not
-- collide. The coverage view reads these rows, so coverage updates immediately.
-- SECURITY INVOKER: RLS applies to the caller.
-- Apply in the SQL editor after 0001-0012. STATUS: written, not yet applied.

create or replace function public.add_commitment(
  p_requirement_line_id uuid,
  p_oem_id uuid,
  p_kind public.commitment_kind,
  p_quantity integer,
  p_unit_price numeric,
  p_expected_date date
)
returns uuid
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_seq integer;
  v_id uuid;
begin
  if p_quantity is null or p_quantity <= 0 then
    raise exception 'Commitment quantity must be greater than zero';
  end if;

  select coalesce(max(shipment_seq), 0) + 1 into v_seq
  from public.commitments
  where requirement_line_id = p_requirement_line_id and oem_id = p_oem_id;

  insert into public.commitments
    (requirement_line_id, oem_id, kind, quantity, unit_price, expected_date, shipment_seq, is_demo)
  values
    (p_requirement_line_id, p_oem_id, p_kind, p_quantity, p_unit_price, p_expected_date, v_seq, false)
  returning id into v_id;

  return v_id;
end;
$$;

-- ==================== supabase/migrations/0014_quote_lifecycle.sql ====================
-- 0014_quote_lifecycle.sql — create a draft quote from a requirement, and approve a quote.
-- Price source: the cheapest firm commitment on the line, else the cheapest OEM product price,
-- else 0; the recommended price is generated from it (0007) and the final price stays human.
-- SECURITY INVOKER: RLS applies to the caller.
-- Apply in the SQL editor after 0001-0013. STATUS: written, not yet applied.

create or replace function public.create_quote_for_requirement(
  p_requirement_id uuid,
  p_margin_pct numeric default 15
)
returns uuid
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_quote uuid;
  v_version uuid;
begin
  if not exists (select 1 from public.requirements where id = p_requirement_id) then
    raise exception 'Requirement % not found', p_requirement_id;
  end if;
  if not exists (select 1 from public.requirement_lines where requirement_id = p_requirement_id) then
    raise exception 'The requirement has no line items to quote';
  end if;

  insert into public.quotes (requirement_id, status, current_version, is_demo)
  values (p_requirement_id, 'draft', 1, false)
  returning id into v_quote;

  insert into public.quote_versions (quote_id, version_no, status, is_demo)
  values (v_quote, 1, 'draft', false)
  returning id into v_version;

  insert into public.quote_version_lines
    (quote_version_id, requirement_line_id, oem_price, lead_time_days, target_margin_pct, is_demo)
  select
    v_version,
    l.id,
    coalesce(
      (select min(c.unit_price) from public.commitments c
        where c.requirement_line_id = l.id and c.kind = 'firm'),
      (select min(op.unit_price) from public.oem_products op where op.part_number = l.part_number),
      0
    ),
    coalesce(
      (select min(op.lead_time_days) from public.oem_products op where op.part_number = l.part_number),
      0
    ),
    p_margin_pct,
    false
  from public.requirement_lines l
  where l.requirement_id = p_requirement_id;

  update public.requirements set status = 'quoted' where id = p_requirement_id and status = 'received';

  return v_quote;
end;
$$;

create or replace function public.approve_quote(p_quote_id uuid)
returns void
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_version integer;
begin
  select current_version into v_version from public.quotes where id = p_quote_id;
  if v_version is null then
    raise exception 'Quote % not found', p_quote_id;
  end if;

  update public.quotes set status = 'approved' where id = p_quote_id;
  update public.quote_versions
     set status = 'approved', approved_at = now()
   where quote_id = p_quote_id and version_no = v_version;
end;
$$;

-- ==================== supabase/migrations/0015_oem_capacity.sql ====================
-- 0015_oem_capacity.sql — A1: OEM capacity as explicit data plus a configuration flag.
-- A1 (docs/ASSUMPTIONS.md): capacity is a GLOBAL pool — available = declared − all firm commitments.
-- If Ram overturns that, it is a flag, not a rewrite: `oems.capacity_shared` says whether capacity
-- is shared across all orders (global) or separate to each order.
-- Declared capacity is per OEM product; `available` and `over_committed` are derived here, never
-- stored. Products with no declared capacity report NULL available (unknown) and are never flagged.
-- SECURITY INVOKER: RLS applies to the caller.
-- Apply in the SQL editor after 0001-0014. STATUS: written, not yet applied.

alter table public.oem_products
  add column if not exists declared_capacity integer
  check (declared_capacity is null or declared_capacity >= 0);

alter table public.oems
  add column if not exists capacity_shared boolean not null default true;

create or replace view public.oem_product_capacity
with (security_invoker = true) as
select
  op.id as oem_product_id,
  op.oem_id,
  op.part_number,
  op.declared_capacity,
  coalesce(sum(c.quantity) filter (where rl.id is not null), 0)::int as firm_committed,
  case
    when op.declared_capacity is null then null
    else greatest(
      op.declared_capacity - coalesce(sum(c.quantity) filter (where rl.id is not null), 0), 0
    )::int
  end as available,
  case
    when op.declared_capacity is null then 0
    else greatest(
      coalesce(sum(c.quantity) filter (where rl.id is not null), 0) - op.declared_capacity, 0
    )::int
  end as over_committed
from public.oem_products op
left join public.commitments c
  on c.oem_id = op.oem_id and c.kind = 'firm'
left join public.requirement_lines rl
  on rl.id = c.requirement_line_id and rl.part_number = op.part_number
group by op.id, op.oem_id, op.part_number, op.declared_capacity;

-- ==================== supabase/migrations/0016_leads.sql ====================
-- 0016_leads.sql — the front of the funnel: a lead captured from a call, WhatsApp or referral.
-- A lead is a pre-RFI opportunity. When it matures it converts to a requirement (the tender system).
-- Apply in the SQL editor after 0001-0015. STATUS: written, not yet applied.

create type lead_source as enum
  ('call','whatsapp','referral','gem','portal','direct','other');
create type lead_stage as enum
  ('new','contacted','qualified','quoted','won','lost');

create table public.leads (
  id uuid primary key default gen_random_uuid(),
  source lead_source not null default 'call',
  name text not null,
  company text,
  phone text,
  email text,
  product_note text,
  stage lead_stage not null default 'new',
  next_follow_up date,
  owner text,
  converted_requirement_id uuid references public.requirements(id),
  is_demo boolean not null default false,
  created_at timestamptz not null default now()
);

create index leads_followup_idx on public.leads(next_follow_up);
create index leads_stage_idx on public.leads(stage);

alter table public.leads enable row level security;

create policy owner_all on public.leads
  for all using (public.is_owner()) with check (public.is_owner());

create policy sales_rw on public.leads
  for all using (public.current_app_role() = 'sales')
  with check (public.current_app_role() = 'sales');

create trigger audit_leads
  after insert or update or delete on public.leads
  for each row execute function public.write_audit();

